/// Look up a Unicode property or category by its canonical name.
pub fn from_name(name: &str) -> Option<CSet> {
    match name {
        "Alphabetic" => Some(alphabetic()),
        "Case_Ignorable" => Some(case_ignorable()),
        "Cased" => Some(cased()),
        "Changes_When_Casefolded" => Some(changes_when_casefolded()),
        "Changes_When_Casemapped" => Some(changes_when_casemapped()),
        "Changes_When_Lowercased" => Some(changes_when_lowercased()),
        "Changes_When_Titlecased" => Some(changes_when_titlecased()),
        "Changes_When_Uppercased" => Some(changes_when_uppercased()),
        "Default_Ignorable_Code_Point" => Some(default_ignorable_code_point()),
        "Grapheme_Base" => Some(grapheme_base()),
        "Grapheme_Extend" => Some(grapheme_extend()),
        "Grapheme_Link" => Some(grapheme_link()),
        "ID_Continue" => Some(id_continue()),
        "ID_Start" => Some(id_start()),
        "InCB; Consonant" => Some(incb_consonant()),
        "InCB; Extend" => Some(incb_extend()),
        "InCB; Linker" => Some(incb_linker()),
        "Lowercase" => Some(lowercase()),
        "Math" => Some(math()),
        "Uppercase" => Some(uppercase()),
        "XID_Continue" => Some(xid_continue()),
        "XID_Start" => Some(xid_start()),
        _ => None,
    }
}
